export const constitutionData: Record<string, string> = {
  "1": "نظام الحكم بالمغرب نظام ملكية دستورية، ديمقراطية برلمانية واجتماعية.\n\nيقوم النظام الدستوري للمملكة على أساس فصل السلط، وتوازنها وتعاونها، والديمقراطية المواطنة والتشاركية، وعلى مبادئ الحكامة الجيدة، وربط المسؤولية بالمحاسبة.\n\nتستند الأمة في حياتها العامة على ثوابت جامعة، تتمثل في الدين الإسلامي السمح، والوحدة الوطنية متعددة الروافد، والملكية الدستورية، والاختيار الديمقراطي.\n\nالتنظيم الترابي للمملكة تنظيم لا مركزي، يقوم على الجهوية المتقدمة.",
  "2": "السيادة للأمة، تمارسها مباشرة بالاستفتاء، وبصفة غير مباشرة بواسطة ممثليها.\n\nتختار الأمة ممثليها في المؤسسات المنتخبة بالاقتراع الحر والنزيه والمنتظم.",
  "3": "الإسلام دين الدولة، والدولة تضمن لكل واحد حرية ممارسة شؤونه الدينية.",
  "4": "علم المملكة هو اللواء الأحمر الذي تتوسطه نجمة خضراء خماسية الفروع.\n\nشعار المملكة: الله، الوطن، الملك.",
  "5": "تظل العربية اللغة الرسمية للدولة. وتعمل الدولة على حمايتها وتطويرها، وتنمية استعمالها.\n\nتعد الأمازيغية أيضاً لغة رسمية للدولة، باعتبارها رصيداً مشتركاً لجميع المغاربة بدون استثناء.\n\nيحدد قانون تنظيمي مراحل تفعيل الطابع الرسمي للأمازيغية، وكيفيات إدماجها في مجال التعليم، وفي مجالات الحياة العامة ذات الأولوية، وذلك لكي تتمكن من القيام مستقبلاً بوظفتها، بصفتها لغة رسمية.\n\nتعمل الدولة على صيانة الحسانية، باعتبارها جزءاً لا يتجزأ من الهوية الثقافية المغربية الموحدة، وعلى حماية اللهجات والتعبيرات الثقافية المستعملة في المغرب، وتسهر على انسجام السياسة اللغوية والثقافية الوطنية، وعلى تعلم وإتقان اللغات الأجنبية الأكثر تداولاً في العالم، باعتبارها وسائل للتواصل، والانخراط في مجتمع المعرفة، والانفتاح على الثقافات، وعلى حضارة العصر.\n\nيُحدث مجلس وطني للغات والثقافة المغربية، مهمته، على الخصوص، حماية وتنمية اللغتين العربية والأمازيغية، ومختلف التعبيرات الثقافية المغربية، باعتبارها تراثاً أصيلاً وإبداعاً معاصراً. ويضم كل المؤسسات المعنية بهذه المجالات. ويحدد قانون تنظيمي صلاحياته وتنظيمه وكيفيات سيره.",
  "6": "القانون هو أسمى تعبير عن إرادة الأمة. والجميع، أشخاصاً ذاتيين أو اعتباريين، بما فيهم السلطات العمومية، متساوون أمامه، وملزمون بالامتثال له.\n\nتعمل السلطات العمومية على توفير الظروف التي تمكن من تعميم الطابع الفعلي لحرية المواطنات والمواطنين، والمساواة بينهم، ومن مشاركتهم في الحياة السياسية والاقتصادية والثقافية والاجتماعية.\n\nتعتبر القواعد القانونية الجديدة غير ذات أثر رجعي، إلا في حالات استثنائية ينص عليها القانون.",
  "7": "تعمل الأحزاب السياسية على تأطير المواطنات والمواطنين وتكوينهم السياسي، وتعزيز انخراطهم في الحياة الوطنية، وفي تدبير الشأن العام، وتساهم في التعبير عن إرادة الناخبين، والمشاركة في ممارسة السلطة، على أساس التعددية والتناوب، بالوسائل الديمقراطية، وفي نطاق المؤسسات الدستورية.\n\nتؤسس الأحزاب السياسية وتمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون.\n\nنظام الحزب الوحيد نظام غير مشروع.\n\nلا يجوز أن تؤسس الأحزاب السياسية على أساس ديني أو لغوي أو عرقي أو جهوي، وبصفة عامة على أي أساس من التمييز أو المخالفة لحقوق الإنسان.\n\nلا يجوز أن يكون هدفها المساس بالدين الإسلامي، أو بالنظام الملكي، أو المبادئ الدستورية، أو الأسس الديمقراطية، أو الوحدة الوطنية أو الترابية للمملكة.\n\nيحدد قانون تنظيمي، في إطار المبادئ الواردة في هذه الفصل، القواعد المتعلقة، على وجه الخصوص، بتأسيس الأحزاب السياسية، ومعايير منح الدعم المالي للدولة، وكذا كيفيات مراقبة تمويلها.",
  "8": "تساهم المنظمات النقابية للأجراء، والغرف المهنية، والمنظمات المهنية للمشغلين، في الدفاع عن الحقوق والمصالح الاقتصادية والاجتماعية للفئات التي تؤطرها، وفي النهوض بها. ويتم تأسيسها وممارسة أنشطتها بحرية، في نطاق احترام الدستور والقانون.\n\nيجب أن تكون هياكل هذه المنظمات وتسييرها مطابقة للمبادئ الديمقراطية.\n\nتعمل السلطات العمومية على تشجيع المفاوضة الجماعية، وعلى إبرام اتفاقيات الشغل الجماعية، وفق الشروط التي يحددها القانون.\n\nيحدد القانون، بصفة خاصة، القواعد المتعلقة بتأسيس المنظمات النقابية، ومعايير منح الدعم المالي للدولة، وكذا كيفيات مراقبة تمويلها.",
  "9": "لا يجوز حل الأحزاب السياسية والمنظمات النقابية، أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي.",
  "10": "يضمن الدستور للمعارضة البرلمانية مكانة تخولها حقوقاً من شأنها تمكينها من النهوض بمهامها، على الوجه الأكمل، في العمل البرلماني والحياة السياسية.\n\nويضمن الدستور، بصفة خاصة، للمعارضة الحقوق التالية:\n- حرية الرأي والتعبير والاجتماع؛\n- الاستفادة من وسائل الإعلام العمومية؛\n- المشاركة الفعلية في المسطرة التشريعية، لاسيما عن طريق تسجيل مقترحات قوانين بجدول أعمال مجلسي البرلمان؛\n- المشاركة الفعلية في مراقبة العمل الحكومي، لاسيما عن طريق ملتمس الرقابة، ومساءلة الحكومة، والأسئلة الشفوية الموجهة للحكومة، واللجان النيابية لتقصي الحقائق؛\n- المساهمة في تقديم ترشيحات، وانتخاب أعضاء المحكمة الدستورية؛\n- تمثيلية ملائمة في الأنشطة الداخلية لمجلسي البرلمان؛\n- رئاسة اللجنة المكلفة بالتشريع بمجلس النواب؛\n- التوفر على وسائل ملائمة للنهوض بمهامها المؤسساتية؛\n- المساهمة الفاعلة في الدبلوماسية البرلمانية، للدفاع عن القضايا الوطنية العادلة ومصالح المملكة الحيوية؛\n- المساهمة في تأطير وتمثيل المواطنات والمواطنين، من خلال الأحزاب السياسية المكونة لها، طبقاً لأحكام الفصل 7 من هذا الدستور؛\n- ممارسة السلطة عن طريق التناوب الديمقراطي، محلياً جهوياً ووطنياً، في نطاق أحكام الدستور.\n\nيجب على فرق المعارضة المساهمة في العمل البرلماني بكيفية فعالة وبناءة.\n\nتحدد كيفيات ممارسة فرق المعارضة لهذه الحقوق، حسب الحالة، بمقتضى قوانين تنظيمية أو قوانين أو بمقتضى النظام الداخلي لكل مجلس من مجلسي البرلمان.",
  "11": "الانتخابات الحرة والنزيهة والشفافة هي أساس مشروعية التمثيل الديمقراطي.\n\nالسلطات العمومية ملزمة بالحياد التام إزاء المترشحين، وبعدم التمييز بينهم.\n\nيحدد القانون القواعد المتعلقة بحدود الدوائر الانتخابية، ونظام الانتخاب، وكيات مراجعة اللوائح الانتخابية، ومراقبة العمليات الانتخابية، وإجراءات الطعن، وكذا القواعد التي تضمن مشاركة المغاربة المقيمين في الخارج في الانتخابات.\n\nيعاقب القانون على كل مخالفة للمقتضيات والقواعد المتعلقة بنزاهة وصدق وشفافية العمليات الانتخابية.",
  "12": "تُؤسس جمعيات المجتمع المدني والمنظمات غير الحكومية وتمارس أنشطتها بحرية، في نطاق احترام الدستور والقانون.\n\nلا يمكن حل هذه الجمعيات والمنظمات أو توقيفها من لدن السلطات العمومية، إلا بمقتضى مقرر قضائي.\n\nتساهم الجمعيات المهتمة بقضايا الشأن العام، والمنظمات غير الحكومية، في إطار الديمقراطية التشاركية، في إعداد قرارات ومشاريع لدى المؤسسات المنتخبة والسلطات العمومية، وكذا في تفعيلها وتقييمها. وعلى هذه المؤسسات والسلطات تنظيم هذه المشاركة، طبقاً لشروط وكيفيات يحددها القانون.\n\nيجب أن يكون تنظيم الجمعيات والمنظمات غير الحكومية وتسييرها مطابقاً للمبادئ الديمقراطية.",
  "13": "تعمل السلطات العمومية على إحداث هيئات للتشاور، قصد إشراك مختلف الفاعلين الاجتماعيين، في إعداد السياسات العمومية وتفعيلها وتنفيذها وتقييمها.",
  "14": "للمواطنات والمواطنين، ضمن شروط وكيفيات يحددها قانون تنظيمي، الحق في تقديم ملتمسات في مجال التشريع.",
  "15": "للمواطنات والمواطنين الحق في تقديم عرائض إلى السلطات العمومية.\n\nويحدد قانون تنظيمي شروط وكيفيات ممارسة هذا الحق.",
  "16": "تعمل المملكة المغربية على حماية الحقوق والمصالح المشروعة للمواطنات والمواطنين المغاربة المقيمين في الخارج، في إطار احترام القانون الدولي والقوانين الجاري بها العمل في بلدان الاستقبال. كما تحرص على الحفاظ على الروابط الإنسانية معهم، ولاسيما الثقافية منها، وتعمل على تنميتها وصيانة هويتهم الوطنية.\n\nتسهر الدولة على تقوية مساهمتهم في تنمية وطنهم، المغرب، وكذا على تمتين أواصر الصداقة والتعاون مع حكومات ومجتمعات بلدان الإقامة، أو التي يعتبرون من مواطنيها.",
  "17": "يتمتع المغاربة المقيمون في الخارج بحقوق المواطنة كاملة، بما فيها حق التصويت والترشيح في الانتخابات. ويمكنهم تقديم ترشيحاتهم للانتخابات على مستوى اللوائح والدوائر الانتخابية، المحلية والجهوية والوطنية. ويحدد القانون المعايير الخاصة بالأهلية للانتخاب وكذا كيفيات ممارسة حق التصويت والترشيح من الخارج.\n\nيسهر القانون على ضمان أوسع مشاركة ممكنة للمغاربة المقيمين في الخارج، في المؤسسات الاستشارية، وهيئات الحكامة الجيدة، التي يحدثها الدستور أو القانون.",
  "18": "تعمل السلطات العمومية على ضمان أوسع مشاركة للشباب في التنمية الاجتماعية والاقتصادية والثقافية والسياسية للبلاد.\n\nوتساعد الشباب على الانخراط في الحياة النشيطة والجمعوية، وتقدم المساعدة لتيسير ولوجهم للثقافة والعلم والتكنولوجيا، والفن والرياضة والأنشطة الترفيهية، مع تهيئة الظروف الكفيلة بتفتق طاقاتهم الخلاقة والمبدعة في كل هذه المجالات.\n\nيُحدث مجلس استشاري للشباب والعمل الجمعوي، لهذا الغرض، طبقاً لأحكام الفصل 33 من هذا الدستور.",
  "19": "يتمتع الرجل والمرأة، على قدم المساواة، بالحقوق والحريات المدنية والسياسية والاقتصادية والاجتماعية والثقافية والبيئية، الواردة في هذا الباب وفي مقتضيات الدستور الأخرى، وكذا في الاتفاقيات والمواثيق الدولية، كما صادق عليها المغرب، وكل ذلك في نطاق أحكام الدستور وثوابت المملكة وقوانينها.\n\nتسعى الدولة إلى تحقيق مبدأ المناصفة بين الرجال والنساء.\n\nتُحدث لهذه الغاية، هيئة للمناصفة ومحاربة جميع أشكال التمييز.",
  "20": "الحق في الحياة هو أسمى حقوق الإنسان. والقانون يحمي هذا الحق.",
  "21": "لكل فرد الحق في سلامة شخصه وأقربائه، وحماية ممتلكاته.\n\nتضمن السلطات العمومية سلامة السكان، وسلامة التراب الوطني، في إطار احترام الحريات والحقوق الأساسية المكفولة للجميع.",
  "22": "لا يجوز المس بالسلامة الجسدية أو المعنوية لأي شخص، في أي ظرف كان، ومن قبل أي جهة كانت، خاصة أو عامة.\n\nلا يجوز لأحد أن يعامل غيره، تحت أي ذريعة، معاملة قاسية أو لاإنسانية أو مهينة أو حاطة بالكرامة الإنسانية.\n\nممارسة التعذيب بكافة أشكاله، ومن قبل أي أحد، جريمة يعاقب عليها القانون.",
  "23": "لا يجوز إلقاء القبض على أي شخص أو اعتقاله أو متابعته أو إدانته إلا في الحالات وطبق الإجراءات التي ينص عليها القانون.\n\nالاعتقال التعسفي أو السري والاختفاء القسري من أخطر الجرائم، وتعرض مقترفيها لأقسى العقوبات.\n\nيجب إخبار كل شخص تم اعتقاله، فوراً وبكيفية يفهمها، بدواعي اعتقاله وبحقوقه، ومن بينها حقه في التزام الصمت. ويحق له الاستفادة، في أقرب وقت ممكن، من مساعدة قانونية، ومن إمكانية الاتصال بأقربائه، طبقاً للقانون.\n\nقرينة البراءة والحق في محاكمة عادلة مضمونان.\n\nيتمتع كل شخص معتقل بحقوق أساسية، وبظروف اعتقال إنسانية. ويمكنه أن يستفيد من برامج للتكوين وإعادة الإدماج.\n\nيُحظر كل تحريض على العنصرية أو الكراهية أو العنف.\n\nيعاقب القانون على جريمة الإبادة وغيرها من الجرائم ضد الإنسانية، وجرائم الحرب، وكافة الانتهاكات الجسيمة والممنهجة لحقوق الإنسان.",
  "24": "لكل شخص الحق في حماية حياته الخاصة.\n\nلا تنتهك حرمة المنزل. ولا يمكن إجراء تفتيش إلا وفق الشروط والإجراءات التي ينص عليها القانون.\n\nلا تنتهك سرية الاتصالات الشخصية، كيفما كان شكلها. ولا يمكن الترخيص بالاطلاع على مضمونها أو نشرها، كلاً أو بعضاً، أو باستعمالها ضد أي كان، إلا بمقتضى أمر قضائي، ووفق الشروط والكيفيات التي ينص عليها القانون.\n\nحرية التنقل عبر التراب الوطني والاستقرار فيه، والخروج منه، والعودة إليه، مضمونة للجميع وفق القانون.",
  "25": "حرية الفكر والرأي والتعبير مكفولة بكل أشكالها.\n\nحرية الإبداع والنشر والعرض في مجالات الأدب والفن والبحث العلمي والتقني مضمونة.",
  "26": "تدعم السلطات العمومية بالوسائل الملائمة، تنمية الإبداع الثقافي والفني، والبحث العلمي والتقني والنهوض بالرياضة. كما تسعى لتيسير ولوج المواطنات والمواطنين للثقافة وللعلم.",
  "27": "للمواطنات والمواطنين حق الحصول على المعلومات، الموجودة في حوزة الإدارة العمومية، والمؤسسات المنتخبة، والهيئات المكلفة بمهام المرفق العام.\n\nلا يمكن تقييد الحق في المعلومة إلا بمقتضى القانون، بهدف حماية كل ما يتعلق بالدفاع الوطني، وحماية أمن الدولة الداخلي والخارجي، والحياة الخاصة للأفراد، وكذا الوقاية من المس بالحريات والحقوق الأساسية المنصوص عليها في هذا الدستور، وحماية مصادر المعلومات والمجالات التي يحددها القانون بدقة.",
  "28": "حرية الصحافة مضمونة، ولا يمكن تقييدها بأي شكل من أشكال الرقابة القبلية.\n\nللجميع الحق في التعبير، ونشر الأخبار والأفكار والآراء، بكل حرية، ومن غير قيد، إلا ما ينص عليه القانون صراحة.\n\nتشجع السلطات العمومية على تنظيم قطاع الصحافة، بكيفية مستقلة، وعلى أسس ديمقراطية، وعلى وضع قواعد قانونية وأخلاقية لعمله.\n\nيحدد القانون قواعد تنظيم وسائل الإعلام العمومية ومراقبتها. ويضمن الاستفادة من هذه الوسائل، مع احترام التعددية اللغوية والثقافية والسياسية للمجتمع المغربي.\n\nتسهر الهيئة العليا للاتصال السمعي البصري على احترام هذه التعددية، وفق أحكام الفصل 165 من هذا الدستور.",
  "29": "حريات الاجتماع والتجمهر والتظاهر السلمي، وتأسيس الجمعيات، والانتماء النقابي والسياسي مضمونة. ويحدد القانون شروط ممارسة هذه الحريات.\n\nحق الإضراب مضمون. ويحدد قانون تنظيمي شروط وكيفيات ممارسته.",
  "30": "لكل مواطنة ومواطن الحق في التصويت، وفي الترشح للانتخابات، شرط بلوغ سن الرشد القانونية، والتوفر على الشروط التي ينص عليها القانون.\n\nيسهر القانون على وضع مقتضيات كفيلة بتشجيع تكافؤ الفرص بين النساء والرجال في ولوج الوظائف الانتخابية.\n\nالتصويت حق شخصي وواجب وطني.\n\nيتمتع الأجانب بالحريات الأساسية المعترف بها للمواطنات والمواطنين المغاربة، وفق القانون.\n\nويمكن للأجانب المقيمين بالمغرب المشاركة في الانتخابات المحلية، بمقتضى القانون أو تطبيقاً لاتفاقيات دولية أو ممارسات المعاملة بالمثل.\n\nيحدد القانون شروط تسليم الأشخاص المتابعين أو المدانين لدول أجنبية، وكذا شروط منح حق اللجوء.",
  "31": "تعمل الدولة والمؤسسات العمومية والجماعات الترابية، على تعبئة كل الوسائل المتاحة، لتيسير أسباب استفادة المواطنات والمواطنين، على قدم المساواة، من الحق في:\n\nالعلاج والعناية الصحية؛\nالحماية الاجتماعية والتغطية الصحية، والتضامن التعاضدي أو المنظم من لدن الدولة؛\n\nالحصول على تعليم عصري ميسر الولوج وذي جودة؛\n\nالتنشئة على التشبث بالهوية المغربية، والثوابت الوطنية الراسخة؛\n\nالتكوين المهني والاستفادة من التربية البدنية والفنية؛\n\nالسكن اللائق؛\n\nالشغل والدعم من طرف السلطات العمومية في البحث عن منصب شغل، أو في التشغيل الذاتي؛\n\nولوج الوظائف العمومية حسب الاستحقاق؛\n\nالحصول على الماء والعيش في بيئة سليمة؛\n\nالتنمية المستدامة.",
  "32": "الأسرة القائمة على علاقة الزواج الشرعي هي الخلية الأساسية للمجتمع.\n\nتعمل الدولة على ضمان الحماية الحقوقية والاجتماعية والاقتصادية للأسرة، بمقتضى القانون، بما يضمن وحدتها واستقرارها والمحافظة عليها.\n\nتسعى الدولة لتوفير الحماية القانونية، والاعتبار الاجتماعي والمعنوي لجميع الأطفال، بكيفية متساوية، بصرف النظر عن وضعيتهم العائلية.\n\nالتعليم الأساسي حق للطفل وواجب على الأسرة والدولة.\n\nيحدث مجلس استشاري للأسرة والطفولة.",
  "33": "على السلطات العمومية اتخاذ التدابير الملائمة لتحقيق ما يلي:\n\nتوسيع وتعميم مشاركة الشباب في التنمية الاجتماعية والاقتصادية والثقافية والسياسية للبلاد؛\nمساعدة الشباب على الاندماج في الحياة النشيطة والجمعوية، وتقديم المساعدة لأولئك الذين تعترضهم صعوبة في التكيف المدرسي أو الاجتماعي أو المهني؛\n\nتيسير ولوج الشباب للثقافة والعلم والتكنولوجيا، والفن والرياضة والأنشطة الترفيهية، مع توفير الظروف المواتية لتفتق طاقاتهم الخلاقة والإبداعية في كل هذه المجالات.\n\nيُحدث مجلس استشاري للشباب والعمل الجمعوي، من أجل تحقيق هذه الأهداف.",
  "34": "تقوم السلطات العمومية بوضع وتفعيل سياسات موجهة إلى الأشخاص والفئات من ذوي الاحتياجات الخاصة. ولهذا الغرض، تسهر خصوصا على ما يلي:\n\nمعالجة الأوضاع الهشة لفئات من النساء والأمهات، وللأطفال والأشخاص المسنين والوقاية منها؛\nإعادة تأهيل الأشخاص الذين يعانون من إعاقة جسدية، أو حسية حركية، أو عقلية، وإدماجهم في الحياة الاجتماعية والمدنية، وتيسير تمتعهم بالحقوق والحريات المعترف بها للجميع.",
  "35": "يضمن القانون حق الملكية.\n\nويمكن الحد من نطاقها وممارستها بموجب القانون، إذا اقتضت ذلك متطلبات التنمية الاقتصادية والاجتماعية للبلاد. ولا يمكن نزع الملكية إلا في الحالات ووفق الإجراءات التي ينص عليها القانون.\n\nتضمن الدولة حرية المبادرة والمقاولة، والتنافس الحر. كما تعمل على تحقيق تنمية بشرية مستدامة، من شأنها تعزيز العدالة الاجتماعية، والحفاظ على الثروات الطبيعية الوطنية، وعلى حقوق الأجيال القادمة.\n\nتسهر الدولة على ضمان تكافؤ الفرص للجميع، والرعاية الخاصة للفئات الاجتماعية الأقل حظا.",
  "36": "يعاقب القانون على المخالفات المتعلقة بحالات تنازع المصالح، وعلى استغلال التسريبات المخلة بالتنافس النزيه، وكل مخالفة ذات طابع مالي.\n\nعلى السلطات العمومية الوقاية، طبقا للقانون، من كل أشكال الانحراف المرتبطة بنشاط الإدارات والهيئات العمومية، وباستعمال الأموال الموجودة تحت تصرفها، وبإبرام الصفقات العمومية وتدبيرها، والزجر عن هذه الانحرافات.\n\nيعاقب القانون على الشطط في استغلال مواقع النفوذ والامتياز، ووضعيات الاحتكار والهيمنة، وباقي الممارسات المخالفة لمبادئ المنافسة الحرة والمشروعة في العلاقات الاقتصادية.\n\nتحدث هيئة وطنية للنزاهة والوقاية من الرشوة ومحاربتها.",
  "37": "على جميع المواطنات والمواطنين احترام الدستور والتقيد بالقانون. ويتعين عليهم ممارسة الحقوق والحريات التي يكفلها الدستور بروح المسؤولية والمواطنة الملتزمة، التي تتلازم فيها ممارسة الحقوق بالنهوض بأداء الواجبات.",
  "38": "يُساهم كل المواطنات والمواطنين في الدفاع عن الوطن ووحدته الترابية تجاه أي عدوان أو تهديد.",
  "39": "على الجميع أن يتحمل، كل على قدر استطاعته، التكاليف العمومية، التي للقانون وحده إحداثها وتوزيعها، وفق الإجراءات المنصوص عليها في هذا الدستور.",
  "40": "على الجميع أن يتحمل، بصفة تضامنية، وبشكل يتناسب مع الوسائل التي يتوفرون عليها، التكاليف التي تتطلبها تنمية البلاد، وكذا تلك الناتجة عن الأعباء الناجمة عن الآفات والكوارث الطبيعية التي تصيب البلاد.",
  "41": "الملك، أمير المؤمنين وحامي حمى الملة والدين، والضامن لحرية ممارسة الشؤون الدينية.\n\nيرأس الملك، أمير المؤمنين، المجلس العلمي الأعلى، الذي يتولى دراسة القضايا التي يعرضها عليه.\n\nويعتبر المجلس الجهة الوحيدة المؤهلة لإصدار الفتاوى التي تعتمد رسميا، في شأن المسائل المحالة إليه، استنادا إلى مبادئ وأحكام الدين الإسلامي الحنيف، ومقاصده السمحة.\n\nتحدد اختصاصات المجلس وتأليفه وكيفيات سيره بظهير.\n\nيمارس الملك الصلاحيات الدينية المتعلقة بإمارة المؤمنين، والمخولة له حصريا، بمقتضى هذا الفصل، بواسطة ظهائر.",
  "42": "الملك رئيس الدولة، وممثلها الأسمى، ورمز وحدة الأمة، وضامن دوام الدولة واستمرارها، والحكم الأسمى بين مؤسساتها، يسهر على احترام الدستور، وحسن سير المؤسسات الدستورية، وعلى صيانة الاختيار الديمقراطي، وحقوق وحريات المواطنين والمواطنات والجماعات، وعلى احترام التعهدات الدولية للمملكة.\n\nالملك هو ضامن استقلال البلاد وحوزة المملكة في دائرة حدودها الحقة.\n\nيمارس الملك هذه المهام، بمقتضى ظهائر، من خلال السلطات المخولة له صراحة بنص الدستور.\n\nتُوقع الظهائر بالعطف من قبل رئيس الحكومة، ماعدا تلك المنصوص عليها في الفصول41 و44 (الفقرة الثانية) و47 (الفقرتان الأولى والسادسة) و51 و57 و59 و130 (الفقرتان الأولى والرابعة) و174.",
  "43": "إن عرش المغرب وحقوقه الدستورية تنتقل بالوراثة إلى الولد الذكر الأكبر سنا من ذرية جلالة الملك محمد السادس، ثم إلى ابنه الأكبر سنا وهكذا ما تعاقبوا، ما عدا إذا عين الملك قيد حياته خلفا له ولدا آخر من أبنائه غير الولد الأكبر سنا، فإن لم يكن ولد ذكر من ذرية الملك، فالمُلك ينتقل إلى أقرب أقربائه من جهة الذكور، ثم إلى ابنه طبق الترتيب والشروط السابقة الذكر.",
  "44": "يعتبر الملك غير بالغ سن الرشد قبل نهاية السنة الثامنة عشرة من عمره. وإلى أن يبلغ سن الرشد، يمارس مجلس الوصاية اختصاصات العرش وحقوقه الدستورية، باستثناء ما يتعلق منها بمراجعة الدستور. ويعمل مجلس الوصاية كهيئة استشارية بجانب الملك حتى يدرك تمام السنة العشرين من عمره.\n\nيرأس مجلس الوصاية رئيس المحكمة الدستورية، ويتركب، بالإضافة إلى رئيسه، من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، والأمين العام للمجلس العلمي الأعلى، وعشر شخصيات يعينهم الملك بمحض اختياره.\n\nقواعد سير مجلس الوصاية تحدد بقانون تنظيمي.",
  "45": "للملك قائمة مدنية.",
  "46": "شخص الملك لا تنتهك حرمته، وللملك واجب التوقير والاحترام.",
  "47": "يعين الملك رئيس الحكومة من الحزب السياسي الذي تصدر انتخابات أعضاء مجلس النواب، وعلى أساس نتائجها.\n\nويعين أعضاء الحكومة باقتراح من رئيسها.\n\nللملك، بمبادرة منه، بعد استشارة رئيس الحكومة، أن يعفي عضوا أو أكثر من أعضاء الحكومة من مهامهم.\n\nولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة.\n\nولرئيس الحكومة أن يطلب من الملك إعفاء عضو أو أكثر، من أعضاء الحكومة، بناء على استقالتهم الفردية أو الجماعية.\n\nيترتب عن استقالة رئيس الحكومة إعفاء الحكومة بكاملها من لدن الملك.\n\nتواصل الحكومة المنتهية مهامها تصريف الأمور الجارية إلى غاية تشكيل الحكومة الجديدة.",
  "48": "يرأس الملك المجلس الوزاري، الذي يتألف من رئيس الحكومة والوزراء.\n\nينعقد المجلس الوزاري بمبادرة من الملك، أو بطلب من رئيس الحكومة.\n\nللملك أن يفوض لرئيس الحكومة، بناء على جدول أعمال محدد، رئاسة مجلس وزاري.",
  "49": "يتداول المجلس الوزاري في القضايا والنصوص التالية:\n\nالتوجهات الاستراتيجية لسياسة الدولة؛\nمشاريع مراجعة الدستور؛\n\nمشاريع القوانين التنظيمية؛\n\nالتوجهات العامة لمشروع قانون المالية؛\n\nمشاريع القوانين - الإطار المشار إليها في الفصل 71 (الفقرة الثانية) من هذا الدستور؛\n\nمشروع قانون العفو العام؛\n\nمشاريع النصوص المتعلقة بالمجال العسكري؛\n\nإعلان حالة الحصار؛\n\nإشهارالحرب؛\n\nمشروع المرسوم المشار إليه في الفصل 104 من هذا الدستور؛\n\nالتعيين باقتراح من رئيس الحكومة، وبمبادرة من الوزير المعني، في الوظائف المدنية الثالية: والي بنك المغرب، والسفراء والولاة والعمال، والمسؤولين عن الإدارات المكلفة بالأمن الداخلي، والمسؤولين عن المؤسسات والمقاولات العمومية الاستراتيجية. وتحدد بقانون تنظيمي لائحة هذه المؤسسات والمقاولات الاستراتيجية.",
  "50": "يصدر الملك الأمر بتنفيذ القانون خلال الثلاثين يوما التالية لإحالته إلى الحكومة بعد تمام الموافقة عليه.\n\nينشر القانون الذي صدر الأمر بتنفيذه، بالجريدة الرسمية للمملكة، خلال أجل أقصاه شهر ابتداء من تاريخ ظهير إصداره.",
  "51": "للملك حق حل مجلسي البرلمان أو أحدهما بظهير، طبق الشروط المبينة في الفصول 96 و97 و98.",
  "52": "للملك أن يخاطب الأمة والبرلمان، ويتلى خطابه أمام كلا المجلسين، ولا يمكن أن يكون مضمونه موضوع أي نقاش داخلهما.",
  "53": "الملك هو القائد الأعلى للقوات المسلحة الملكية. وله حق التعيين في الوظائف العسكرية، كما له أن يفوض لغيره ممارسة هذا الحق.",
  "54": "يُحدث مجلس أعلى للأمن، بصفته هيئة للتشاور بشأن استراتيجيات الأمن الداخلي والخارجي للبلاد، وتدبير حالات الأزمات، والسهر أيضا على مأسسة ضوابط الحكامة الأمنية الجيدة.\n\nيرأس الملك هذا المجلس، وله أن يفوض لرئيس الحكومة صلاحية رئاسة اجتماع لهذا المجلس، على أساس جدول أعمال محدد.\n\nيضم المجلس الأعلى للأمن في تركيبته، علاوة على رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، والرئيس المنتدب للمجلس الأعلى للسلطة القضائية، الوزراء المكلفين بالداخلية، والشؤون الخارجية، والعدل، وإدارة الدفاع الوطني، وكذا المسؤولين عن الإدارات الأمنية، وضباط سامين بالقوات المسلحة الملكية، وكل شخصية أخرى يُعتبر حضورها مفيدا لأشغال المجلس.\n\nويحدد نظام داخلي للمجلس قواعد تنظيمه وتسييره.",
  "55": "يعتمد الملك السفراء لدى الدول الأجنبية والمنظمات الدولية، ولديه يُعتمد السفراء، وممثلو المنظمات الدولية.\n\nيوقع الملك على المعاهدات ويصادق عليها، غير أنه لا يصادق على معاهدات السلم أو الاتحاد، أو التي تهم رسم الحدود، ومعاهدات التجارة، أو تلك التي تترتب عليها تكاليف تلزم مالية الدولة، أو يستلزم تطبيقها اتخاذ تدابير تشريعية، أو تتعلق بحقوق وحريات المواطنات والمواطنين، العامة أو الخاصة، إلا بعد الموافقة عليها بقانون.\n\nللملك أن يعرض على البرلمان كل معاهدة أو اتفاقية أخرى قبل المصادقة عليها.\n\nإذا صرحت المحكمة الدستورية، إثر إحالة الملك، أو رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو سدس أعضاء المجلس الأول، أو ربع أعضاء المجلس الثاني، الأمر إليها، أن التزاما دوليا يتضمن بندا يخالف الدستور، فإن المصادقة على هذا الالتزام لا تقع إلا بعد مراجعة الدستور.",
  "56": "يرأس الملك المجلس الأعلى للسلطة القضائية.",
  "57": "يوافق الملك بظهير على تعيين القضاة من قبل المجلس الأعلى للسلطة القضائية.",
  "58": "يمارس الملك حق العفو.",
  "59": "إذا كانت حوزة التراب الوطني مهددة، أو وقع من الأحداث ما يعرقل السير العادي للمؤسسات الدستورية، أمكن للملك أن يُعلن حالة الاستثناء بظهير، بعد استشارة كل من رئيس الحكومة، ورئيس مجلس النواب، ورئيس مجلس المستشارين، ورئيس المحكمة الدستورية، وتوجيه خطاب إلى الأمة. ويُخول الملك بذلك صلاحية اتخاذ الإجراءات التي يفرضها الدفاع عن الوحدة الترابية، ويقتضيها الرجوع، في أقرب الآجال، إلى السير العادي للمؤسسات الدستورية.\n\nلا يحل البرلمان أثناء ممارسة السلطات الاستثنائية.\n\nتبقى الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور مضمونة.\n\nتُرفع حالة الاستثناء بمجرد انتفاء الأسباب التي دعت إليها، وباتخاذ الإجراءات الشكلية المقررة لإعلانها.",
  "60": "يتكون البرلمان من مجلسين، مجلس النواب ومجلس المستشارين؛ ويستمد أعضاؤه نيابتهم من الأمة، وحقهم في التصويت حق شخصي لا يمكن تفويضه.\n\nالمعارضة مكون أساسي في المجلسين، وتشارك في وظيفتي التشريع والمراقبة، طبقا لما هو منصوص عليه خاصة في هذا الباب.",
  "61": "يجرد من صفة عضو في أحد المجلسين، كل من تخلى عن انتمائه السياسي الذي ترشح باسمه للانتخابات، أو عن الفريق أو المجموعة البرلمانية التي ينتمي إليها.\n\nوتصرح المحكمة الدستورية بشغور المقعد، بناء على إحالة من رئيس المجلس الذي يعنيه الأمر، وذلك وفق أحكام النظام الداخلي للمجلس المعني، الذي يحدد أيضا آجال ومسطرة الإحالة على المحكمة الدستورية.",
  "62": "ينتخب أعضاء مجلس النواب بالاقتراع العام المباشر لمدة خمس سنوات، وتنتهي عضويتهم عند افتتاح دورة أكتوبر من السنة الخامسة التي تلي انتخاب المجلس.\n\nيبين قانون تنظيمي عدد أعضاء مجلس النواب، ونظام انتخابهم، ومبادئ التقسيم الانتخابي، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية.\n\nيُنتخب رئيس مجلس النواب وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم في سنتها الثالثة عند دورة أبريل لما تبقى من الفترة المذكورة.\n\nيُنتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.",
  "63": "يتكون مجلس المستشارين من 90 عضوا على الأقل، و120 عضوا على الأكثر، ينتخبون بالاقتراع العام غير المباشر، لمدة ست سنوات، على أساس التوزيع التالي:\n\nثلاثة أخماس الأعضاء يمثلون جماعات الترابية، يتوزعون بين جهات المملكة بالتناسب مع عدد سكانها، ومع مراعاة الإنصاف بين الجهات. ينتخب المجلس الجهوي على مستوى كل جهة، من بين أعضائه، الثلث المخصص للجهة من هذا العدد. وينتخب الثلثان المتبقيان من قبل هيئة ناخبة تتكون على مستوى الجهة، من أعضاء المجالس الجماعية ومجالس العمالات والأقاليم؛\nخمسان من الأعضاء تنتخبهم، في كل جهة، هيئات ناخبة تتألف من المنتخبين في الغرف المهنية، وفي المنظمات المهنية للمشغلين الأكثر تمثيلية، وأعضاء تنتخبهم على الصعيد الوطني، هيئة ناخبة مكونة من ممثلي المأجورين.\n\nويبين قانون تنظيمي عدد أعضاء مجلس المستشارين، ونظام انتخابهم، وعدد الأعضاء الذين تنتخبهم كل هيئة ناخبة، وتوزيع المقاعد على الجهات، وشروط القابلية للانتخاب، وحالات التنافي، وقواعد الحد من الجمع بين الانتدابات، ونظام المنازعات الانتخابية.\n\nيُنتخب رئيس مجلس المستشارين وأعضاء المكتب، ورؤساء اللجان الدائمة ومكاتبها، في مستهل الفترة النيابية، ثم عند انتهاء منتصف الولاية التشريعية للمجلس.\n\nينتخب أعضاء المكتب على أساس التمثيل النسبي لكل فريق.",
  "64": "لا يمكن متابعة أي عضو من أعضاء البرلمان، ولا البحث عنه، ولا إلقاء القبض عليه، ولا اعتقاله ولا محاكمته، بمناسبة إبدائه لرأي أو قيامه بتصويت خلال مزاولته لمهامه، ماعدا إذا كان الرأي المعبر عنه يجادل في النظام الملكي أو الدين الإسلامي، أو يتضمن ما يخل بالاحترام الواجب للملك.",
  "65": "يعقد البرلمان جلساته أثناء دورتين في السنة، ويرأس الملك افتتاح الدورة الأولى، التي تبتدئ يوم الجمعة الثانية من شهر أكتوبر، وتُفتتح الدورة الثانية يوم الجمعة الثانية من شهر أبريل.\n\nإذا استمرت جلسات البرلمان أربعة أشهر على الأقل في كل دورة، جاز ختم الدورة بمرسوم.",
  "66": "يمكن جمع البرلمان في دورة استثنائية، إما بمرسوم، أو بطلب من ثلث أعضاء مجلس النواب، أو بأغلبية أعضاء مجلس المستشارين.\n\nتعقد دورة البرلمان الاستثنائية على أساس جدول أعمال محدد، وعندما تتم المناقشة في القضايا التي يتضمنها جدول الأعمال، تُختم الدورة بمرسوم.",
  "67": "للوزراء أن يحضروا جلسات كلا المجلسين واجتماعات لجانهما، ويمكنهم أن يستعينوا بمندوبين يعينونهم لهذا الغرض.\n\nعلاوة على اللجان الدائمة المشار إليها في الفقرة السابقة، يجوز أن تشكل بمبادرة من الملك، أو بطلب من ثلث أعضاء مجلس النواب، أو ثلث أعضاء مجلس المستشارين، لجان نيابية لتقصي الحقائق، يُناط بها جمع المعلومات المتعلقة بوقائع معينة، أو بتدبير المصالح أوالمؤسسات والمقاولات العمومية، وإطلاع المجلس الذي شكلها على نتائج أعمالها.\n\nولا يجوز تكوين لجان لتقصي الحقائق في وقائع تكون موضوع متابعات قضائية، ما دامت هذه المتابعات جارية؛ وتنتهي مهمة كل لجنة لتقصي الحقائق، سبق تكوينها، فور فتح تحقيق قضائي في الوقائع التي اقتضت تشكيلها.\n\nلجان تقصي الحقائق مؤقتة بطبيعتها، وتنتهي أعمالها بإيداع تقريرها لدى مكتب المجلس المعني، وعند الاقتضاء، بإحالته إلى القضاء من قبل رئيس هذا المجلس.\n\nتخصص جلسة عمومية داخل المجلس المعني لمناقشة تقارير لجان تقصي الحقائق.\n\nيحدد قانون تنظيمي طريقة تسيير هذه اللجان.",
  "68": "جلسات مجلسي البرلمان عمومية، وينشر محضر مناقشات الجلسات العامة برمته في الجريدة الرسمية للبرلمان.\n\nلكل من المجلسين أن يعقد اجتماعات سرية، بطلب من رئيس الحكومة، أو بطلب من ثلث أعضائه.\n\nجلسات لجان البرلمان سرية، ويحدد النظام الداخلي لمجلسي البرلمان الحالات والضوابط التي يمكن أن تنعقد فيها اللجان بصفة علنية.\n\nيعقد البرلمان جلسات مشتركة بمجلسيه، وعلى وجه الخصوص، في الحالات التالية:\n\nافتتاح الملك للدورة التشريعية في الجمعة الثانية من شهر أكتوبر، والاستماع إلى الخطب الملكية الموجهة للبرلمان؛\nالمصادقة على مراجعة الدستور وفق أحكام الفصل 174؛\n\nالاستماع إلى التصريحات التي يقدمها رئيس الحكومة؛\n\nعرض مشروع قانون المالية السنوي؛\n\nالاستماع إلى خطب رؤساء الدول والحكومات الأجنبية.\n\nكما يمكن لرئيس الحكومة أن يطلب من رئيسي مجلسي النواب والمستشارين عقد اجتماعات مشتركة للبرلمان، للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما.\n\nتنعقد الاجتماعات المشتركة برئاسة رئيس مجلس النواب. ويحدد النظام الداخلي للمجلسين كيفيات وضوابط انعقادها.\n\nعلاوة على الجلسات المشتركة، يمكن للجان الدائمة للبرلمان، أن تعقد اجتماعات مشتركة للاستماع إلى بيانات تتعلق بقضايا تكتسي طابعا وطنيا هاما، وذلك وفق ضوابط يحددها النظامان الداخليان للمجلسين.",
  "69": "يضع كل من المجلسين نظامه الداخلي ويقره بالتصويت، إلا أنه لا يجوز العمل به إلا بعد أن تصرح المحكمة الدستورية بمطابقته لأحكام هذا الدستور.\n\nيتعين على المجلسين، في وضعهما لنظاميهما الداخليين، مراعاة تناسقهما وتكاملهما، ضمانا لنجاعة العمل البرلماني.\n\nيحدد النظام الداخلي بصفة خاصة:\n\nقواعد تأليف وتسيير الفرق والمجموعات البرلمانية والانتساب إليها، والحقوق الخاصة المعترف بها لفرق المعارضة؛\nواجبات الأعضاء في المشاركة الفعلية في أعمال اللجان والجلسات العامة، والجزاءات المطبقة في حالة الغياب؛\n\nعدد اللجان الدائمة واختصاصها وتنظيمها، مع تخصيص رئاسة لجنة أو لجنتين للمعارضة، على الأقل، مع مراعاة مقتضيات الفصل 10 من هذا الدستور.",
  "70": "يمارس البرلمان السلطة التشريعية.\n\nيصوت البرلمان على القوانين، ويراقب عمل الحكومة، ويقيم السياسات العمومية.\n\nللقانون أن يأذن للحكومة أن تتخذ في ظرف من الزمن محدود، ولغاية معينة، بمقتضى مراسيم تدابير يختص القانون عادة باتخاذها، ويجري العمل بهذه المراسيم بمجرد نشرها. غير أنه يجب عرضها على البرلمان بقصد المصادقة، عند انتهاء الأجل الذي حدده قانون الإذن بإصدارها، ويبطل قانون الإذن إذا ما وقع حل مجلسي البرلمان أو أحدهما.",
  "71": "يختص القانون، بالإضافة إلى المواد المسندة إليه صراحة بفصول أخرى من الدستور، بالتشريع في الميادين التالية:\n\nالحقوق والحريات الأساسية المنصوص عليها في التصدير، وفي فصول أخرى من هذا الدستور؛\nنظام الأسرة والحالة المدنية؛\n\nمبادئ وقواعد المنظومة الصحية؛\n\nنظام الوسائط السمعية البصرية والصحافة بمختلف أشكالها؛\n\nالعفو العام؛\n\nالجنسية ووضعية الأجانب؛\n\nتحديد الجرائم والعقوبات الجارية عليها؛\n\nالتنظيم القضائي وإحداث أصناف جديدة من المحاكم؛\n\nالمسطرة المدنية والمسطرة الجنائية؛\n\nنظام السجون؛\n\nالنظام الأساسي العام للوظيفة العمومية؛\n\nالضمانات الأساسية الممنوحة للموظفين المدنيين والعسكريين؛\n\nنظام مصالح وقوات حفظ الأمن؛\n\nنظام الجماعات الترابية ومبادئ تحديد دوائرها الترابية؛\n\nالنظام الانتخابي للجماعات الترابية ومبادئ تقطيع الدوائر الانتخابية؛\n\nالنظام الضريبي، ووعاء الضرائب، ومقدارها وطرق تحصيلها؛\n\nالنظام القانوني لإصدار العملة ونظام البنك المركزي؛\n\nنظام الجمارك؛\n\nنظام الالتزامات المدنية والتجارية، وقانون الشركات والتعاونيات؛\n\nالحقوق العينية وأنظمة الملكية العقارية العمومية والخاصة والجماعية؛\n\nنظام النقل؛\n\nعلاقات الشغل، والضمان الاجتماعي، وحوادث الشغل، والأمراض المهنية؛\n\nنظام الأبناك وشركات التأمين والتعاضديات؛\n\nنظام تكنولوجيا المعلومات والاتصالات؛\n\nالتعمير وإعداد التراب؛\n\nالقواعد المتعلقة بتدبير البيئة وحماية الموارد الطبيعية والتنمية المستدامة؛\n\nنظام المياه والغابات والصيد؛\n\nتحديد التوجهات والتنظيم العام لميادين التعليم والبحث العلمي والتكوين المهني؛\n\nإحداث المؤسسات العمومية وكل شخص اعتباري من أشخاص القانون العام؛\n\nتأميم المنشآت ونظام الخوصصة.\n\nللبرلمان، بالإضافة إلى الميادين المشار إليها في الفقرة السابقة، صلاحية التصويت على قوانين تضع إطارا للأهداف الأساسية لنشاط الدولة، في الميادين الاقتصادية والاجتماعية والبيئية والثقافية.",
  "72": "يختص المجال التنظيمي بالمواد التي لا يشملها اختصاص القانون.",
  "73": "يمكن تغيير النصوص التشريعية من حيث الشكل بمرسوم، بعد موافقة المحكمة الدستورية، إذا كان مضمونها يدخل في مجال من المجالات التي تمارس فيها السلطة التنظيمية اختصاصها.",
  "74": "يمكن الإعلان لمدة ثلاثين يوما عن حالة الحصار، بمقتضى ظهير يوقعه بالعطف رئيس الحكومة، ولا يمكن تمديد هذا الأجل إلا بالقانون.",
  "75": "يصدر قانون المالية، الذي يودع بالأسبقية لدى مجلس النواب، بالتصويت من قبل البرلمان، وذلك طبق الشروط المنصوص عليها في قانون تنظيمي؛ ويحدد هذا القانون التنظيمي طبيعة المعلومات والوثائق والمعطيات الضرورية لتعزيز المناقشة البرلمانية حول مشروع قانون المالية.\n\nيصوت البرلمان مرة واحدة على نفقات التجهيز التي يتطلبها، في مجال التنمية، إنجاز المخططات التنموية الاستراتيجية، والبرامج متعددة السنوات، التي تعدها الحكومة وتطلع عليها البرلمان، وعندما يوافق على تلك النفقات، ويستمر مفعول الموافقة تلقائيا على النفقات طيلة مدة هذه المخططات والبرامج، وللحكومة وحدها الصلاحية لتقديم مشاريع قوانين ترمي إلى تغيير ما تمت الموافقة عليه في الإطار المذكور.\n\nإذا لم يتم في نهاية السنة المالية التصويت على قانون المالية أو لم يصدر الأمر بتنفيذه، بسبب إحالته إلى المحكمة الدستورية، تطبيقا للفصل 132 من الدستور، فإن الحكومة تفتح بمرسوم الاعتمادات اللازمة لسير المرافق العمومية، والقيام بالمهام المنوطة بها، على أساس ما هو مقترح في الميزانية المعروضة على الموافقة.\n\nويُسترسل العمل، في هذه الحالة، باستخلاص المداخيل طبقا للمقتضيات التشريعية والتنظيمية الجارية عليها، باستثناء المداخيل المقترح إلغاؤها في مشروع قانون المالية؛ أما المداخيل التي ينص المشروع المذكور على تخفيض مقدارها، فتُستخلص على أساس المقدار الجديد المقترح.",
  "76": "تعرض الحكومة سنويا على البرلمان، قانون التصفية المتعلق بتنفيذ قانون المالية، خلال السنة الثانية التي تلي سنة تنفيذ هذا القانون. ويتضمن قانون التصفية حصيلة ميزانيات التجهيز التي انتهت مدة نفادها.",
  "77": "يسهر البرلمان والحكومة على الحفاظ على توازن مالية الدولة.\n\nوللحكومة أن ترفض، بعد بيان الأسباب، المقترحات والتعديلات التي يتقدم بها أعضاء البرلمان، إذا كان قبولها يؤدي بالنسبة لقانون المالية إلى تخفيض الموارد العمومية، أو إلى إحداث تكليف عمومي، أو الزيادة في تكليف موجود.",
  "78": "لرئيس الحكومة ولأعضاء البرلمان على السواء حق التقدم باقتراح القوانين.\n\nتودع مشاريع القوانين بالأسبقية لدى مكتب مجلس النواب، غير أن مشاريع القوانين المتعلقة، على وجه الخصوص، بالجماعات الترابية وبالتنمية الجهوية، وبالقضايا الاجتماعية، تودع بالأسبقية لدى مكتب مجلس المستشارين.",
  "79": "للحكومة أن تدفع بعدم قبول كل مقترح أو تعديل لا يدخل في مجال القانون.\n\nكل خلاف في هذا الشأن تبت فيه المحكمة الدستورية، في أجل ثمانية أيام، بطلب من أحد رئيسي المجلسين، أو من رئيس الحكومة.",
  "80": "تحال مشاريع ومقترحات القوانين لأجل النظر فيها على اللجان التي يستمر عملها خلال الفترات الفاصلة بين الدورات.",
  "81": "يمكن للحكومة أن تصدر، خلال الفترة الفاصلة بين الدورات، وباتفاق مع اللجان التي يعنيها الأمر في كلا المجلسين، مراسيم قوانين، يجب عرضها بقصد المصادقة عليها من طرف البرلمان، خلال دورته العادية الموالية.\n\nيودع مشروع المرسوم بقانون لدى مكتب مجلس النواب، وتناقشه بالتتابع اللجان المعنية في كلا المجلسين، بغية التوصل داخل أجل ستة أيام، إلى قرار مشترك بينهما في شأنه. وإذا لم يحصل هذا الاتفاق، فإن القرار يرجع إلى اللجنة المعنية في مجلس النواب.",
  "82": "يضع مكتب كل من مجلسي البرلمان جدول أعماله. ويتضمن هذا الجدول مشاريع القوانين ومقترحات القوانين، بالأسبقية ووفق الترتيب الذي تحدده الحكومة.\n\nيخصص يوم واحد على الأقل في الشهر لدراسة مقترحات القوانين، ومن بينها تلك المقدمة من قبل المعارضة.",
  "83": "لأعضاء مجلسي البرلمان وللحكومة حق التعديل. وللحكومة، بعد افتتاح المناقشة، أن تعارض في بحث كل تعديل لم يُعرض من قبل على اللجنة التي يعنيها الأمر.\n\nيبت المجلس المعروض عليه النص، بتصويت واحد، في النص المتناقش فيه، كله أو بعضه إذا ما طلبت الحكومة ذلك، مع الاقتصار على التعديلات المقترحة أو المقبولة من قبلها. وبإمكان المجلس المعني بالأمر أن يعترض على هذه المسطرة بأغلبية أعضائه.",
  "84": "يتداول مجلسا البرلمان بالتتابع في كل مشروع أو مقترح قانون، بغية التوصل إلى المصادقة على نص واحد؛ ويتداول مجلس النواب بالأسبقية، وعلى التوالي، في مشاريع القوانين، وفي مقترحات القوانين التي قدمت بمبادرة من أعضائه. ويتداول مجلس المستشارين بدوره بالأسبقية، وعلى التوالي، في مشاريع القوانين وكذا في مقترحات القوانين التي هي من مبادرة أعضائه؛ ويتداول كل مجلس في النص الذي صوت عليه المجلس الآخر في الصيغة التي أحيل بها إليه.\n\nويعود لمجلس النواب التصويت النهائي على النص الذي تم البت فيه، ولا يقع هذا التصويت إلا بالأغلبية المطلقة لأعضائه الحاضرين، إذا تعلق الأمر بنص يخص الجماعات الترابية، والمجالات ذات الصلة بالتنمية الجهوية والشؤون الاجتماعية.",
  "85": "لا يتم التداول في مشاريع ومقترحات القوانين التنظيمية من قبل مجلس النواب، إلا بعد مضي عشرة أيام على وضعها لدى مكتبه، ووفق المسطرة المشار إليها في الفصل 84، وتتم المصادقة عليها نهائيا بالأغلبية المطلقة للأعضاء الحاضرين من المجلس المذكور؛ غير أنه إذا تعلق الأمر بمشروع أو بمقترح قانون تنظيمي يخص مجلس المستشارين أو الجماعات الترابية، فإن التصويت يتم بأغلبية أعضاء مجلس النواب.\n\nيجب أن يتم إقرار القوانين التنظيمية المتعلقة بمجلس المستشارين، باتفاق بين مجلسي البرلمان، على نص موحد.\n\nلا يمكن إصدار الأمر بتنفيذ القوانين التنظيمية، إلا بعد أن تصرح المحكمة الدستورية بمطابقتها للدستور.",
  "86": "تعرض مشاريع القوانين التنظيمية المنصوص عليها في هذا الدستور وجوبا قصد المصادقة عليها من قبل البرلمان، في أجل لا يتعدى مدة الولاية التشريعية الأولى التي تلي صدور الأمر بتنفيذ هذا الدستور.",
  "87": "تتألف الحكومة من رئيس الحكومة والوزراء، ويمكن أن تضم كتابا للدولة.\n\nيُحدد قانون تنظيمي، خاصة، القواعد المتعلقة بتنظيم وتسيير أشغال الحكومة والوضع القانوني لأعضائها.\n\nويحدد هذا القانون التنظيمي أيضا حالات التنافي مع الوظيفة الحكومية، وقواعد الحد من الجمع بين المناصب، والقواعد الخاصة بتصريف الحكومة المنتهية مهامها للأمور الجارية.",
  "88": "بعد تعيين الملك لأعضاء الحكومة، يتقدم رئيس الحكومة أمام مجلسي البرلمان مجتمعين، ويعرض البرنامج الذي يعتزم تطبيقه. ويجب أن يتضمن هذا البرنامج الخطوط الرئيسية للعمل الذي تنوي الحكومة القيام به، في مختلف مجالات النشاط الوطني، وبالأخص في ميادين السياسة الاقتصادية والاجتماعية والبيئية والثقافية والخارجية.\n\nيكون البرنامج المشار إليه أعلاه، موضوع مناقشة أمام كلا المجلسين، يعقبها تصويت في مجلس النواب.\n\nتعتبر الحكومة منصبة بعد حصولها على ثقة مجلس النواب، المعبر عنها بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم، لصالح البرنامج الحكومي.",
  "89": "تمارس الحكومة السلطة التنفيذية.\n\nتعمل الحكومة، تحت سلطة رئيسها، على تنفيذ البرنامج الحكومي وعلى ضمان تنفيذ القوانين. والإدارة موضوعة تحت تصرفها، كما تمارس الإشراف والوصاية على المؤسسات والمقاولات العمومية.",
  "90": "يمارس رئيس الحكومة السلطة التنظيمية، ويمكن أن يفوض بعض سلطه إلى الوزراء.\n\nتحمل المقررات التنظيمية الصادرة عن رئيس الحكومة التوقيع بالعطف من لدن الوزراء المكلفين بتنفيذها.",
  "91": "يعين رئيس الحكومة في الوظائف المدنية في الإدارات العمومية، وفي الوظائف السامية في المؤسسات والمقاولات العمومية، دون إخلال بأحكام الفصل 49 من هذا الدستور.\n\nيمكن لرئيس الحكومة تفويض هذه السلطة.",
  "92": "يتداول مجلس الحكومة، تحت رئاسة رئيس الحكومة، في القضايا والنصوص التالية:\n\nالسياسة العامة للدولة قبل عرضها على المجلس الوزاري؛\nالسياسات العمومية؛\n\nالسياسات القطاعية؛\n\nطلب الثقة من مجلس النواب، قصد مواصلة الحكومة تحمل مسؤوليتها؛\n\nالقضايا الراهنة المرتبطة بحقوق الإنسان وبالنظام العام؛\n\nمشاريع القوانين، ومن بينها مشروع قانون المالية، قبل إيداعها بمكتب مجلس النواب، دون إخلال بالأحكام الواردة في الفصل 49 من هذا الدستور؛\n\nمراسيم القوانين؛\n\nمشاريع المراسيم التنظيمية؛\n\nمشاريع المراسيم المشار إليها في الفصول 65 (الفقرة الثانية) و66 و70 (الفقرة الثالثة) من هذا الدستور؛\n\nالمعاهدات والاتفاقيات الدولية قبل عرضها على المجلس الوزاري؛\n\nتعيين الكتاب العامين، ومديري الإدارات المركزية بالإدارات العمومية، ورؤساء الجامعات والعمداء، ومديري المدارس والمؤسسات العليا. وللقانون التنظيمي المشار إليه في الفصل 49 من هذا الدستور، أن يتمم لائحة الوظائف التي يتم التعيين فيها في مجلس الحكومة. ويحدد هذا القانون التنظيمي، على وجه الخصوص، مبادئ ومعايير التعيين في هذه الوظائف، لاسيما منها مبادئ تكافؤ الفرص والاستحقاق والكفاءة والشفافية.\n\nيطلع رئيس الحكومة الملك على خلاصات مداولات مجلس الحكومة.",
  "93": "الوزراء مسؤولون عن تنفيذ السياسة الحكومية كل في القطاع المكلف به، وفي إطار التضامن الحكومي.\n\nيقوم الوزراء بأداء المهام المسندة إليهم من قبل رئيس الحكومة، ويطلعون مجلس الحكومة على ذلك.\n\nيمكن للوزراء أن يفوضوا جزءا من اختصاصاتهم إلى كتاب الدولة.",
  "94": "أعضاء الحكومة مسؤولون جنائيا أمام محاكم المملكة، عما يرتكبون من جنايات وجنح، أثناء ممارستهم لمهامهم.\n\nيُحدد القانون المسطرة المتعلقة بهذه المسؤولية.",
  "95": "للملك أن يطلب من كلا مجلسي البرلمان أن يقرأ قراءة جديدة كل مشروع أو مقترح قانون.\n\nتُطلب القراءة الجديدة بخطاب، ولا يمكن أن ترفض هذه القراءة الجديدة.",
  "96": "للملك، بعد استشارة رئيس المحكمة الدستورية وإخبار رئيس الحكومة ورئيس مجلس النواب، ورئيس مجلس المستشارين، أن يحل بظهير المجلسين معا أو أحدهما.\n\nيقع الحل بعد خطاب يوجهه الملك إلى الأمة.",
  "97": "يتم انتخاب البرلمان الجديد أو المجلس الجديد في ظرف شهرين على الأكثر بعد تاريخ الحل.",
  "98": "إذا وقع حل أحد المجلسين، فلا يمكن حل المجلس الذي يليه إلا بعد مضي سنة على انتخابه، ما عدا في حالة تعذر توفر أغلبية حكومية داخل مجلس النواب الجديد.",
  "99": "يتم اتخاذ قرار إشهار الحرب داخل المجلس الوزاري، طبقا للفصل 49 من هذا الدستور، وبعد إحاطة البرلمان علما بذلك من لدن الملك.",
  "100": "تُخصص بالأسبقية جلسة في كل أسبوع لأسئلة أعضاء مجلسي البرلمان وأجوبة الحكومة.\n\nتُدلي الحكومة بجوابها خلال العشرين يوما الموالية لإحالة السؤال إليها.\n\nتُقدم الأجوبة على الأسئلة المتعلقة بالسياسة العامة من قبل رئيس الحكومة، وتخصص لهذه الأسئلة جلسة واحدة كل شهر، وتُقدم الأجوبة عنها أمام المجلس الذي يعنيه الأمر خلال الثلاثين يوما الموالية لإحالة الأسئلة إلى رئيس الحكومة.",
  "101": "يعرض رئيس الحكومة أمام البرلمان الحصيلة المرحلية لعمل الحكومة، إما بمبادرة منه، أو بطلب من ثلث أعضاء مجلس النواب، أو من أغلبية أعضاء مجلس المستشارين.\n\nتُخصص جلسة سنوية من قبل البرلمان لمناقشة السياسات العمومية وتقييمها.",
  "102": "يمكن للجان المعنية في كلا المجلسين أن تطلب الاستماع إلى مسؤولي الإدارات والمؤسسات والمقاولات العمومية، بحضور الوزراء المعنيين، وتحت مسؤوليتهم.",
  "103": "يمكن لرئيس الحكومة أن يربط، لدى مجلس النواب، مواصلة الحكومة تحمل مسؤوليتها بتصويت يمنح الثقة بشأن تصريح يدلي به في موضوع السياسة العامة، أو بشأن نص يطلب الموافقة عليه.\n\nلا يمكن سحب الثقة من الحكومة، أو رفض النص، إلا بالأغلبية المطلقة للأعضاء الذين يتألف منهم مجلس النواب.\n\nلا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على تاريخ طرح مسألة الثقة.\n\nيؤدي سحب الثقة إلى استقالة الحكومة استقالة جماعية.",
  "104": "يمكن لرئيس الحكومة حل مجلس النواب، بعد استشارة الملك ورئيس المجلس، ورئيس المحكمة الدستورية، بمرسوم يتخذ في مجلس وزاري.\n\nيقدم رئيس الحكومة أمام مجلس النواب تصريحا يتضمن، بصفة خاصة، دوافع قرار الحل وأهدافه.",
  "105": "لمجلس النواب أن يعارض في مواصلة الحكومة تحمل مسؤوليتها، بالتصويت على ملتمس للرقابة؛ ولا يقبل هذا الملتمس إلا إذا وقعه على الأقل خُمس الأعضاء الذين يتألف منهم المجلس.\n\nلا تصح الموافقة على ملتمس الرقابة من قبل مجلس النواب، إلا بتصويت الأغلبية المطلقة للأعضاء الذين يتألف منهم.\n\nلا يقع التصويت إلا بعد مضي ثلاثة أيام كاملة على إيداع الملتمس؛ وتؤدي الموافقة على ملتمس الرقابة إلى استقالة الحكومة استقالة جماعية.\n\nإذا وقعت موافقة مجلس النواب على ملتمس الرقابة، فلا يقبل بعد ذلك تقديم أي ملتمس رقابة أمامه، طيلة سنة.",
  "106": "لمجلس المستشارين أن يُسائل الحكومة بواسطة ملتمس يوقعه على الأقل خُمس أعضائه؛ ولا يقع التصويت عليه، بعد مضي ثلاثة أيام كاملة على إيداعه، إلا بالأغلبية المطلقة لأعضاء هذا المجلس.\n\nيبعث رئيس مجلس المستشارين، على الفور، بنص ملتمس المساءلة إلى رئيس الحكومة ؛ ولهذا الأخير أجل ستة أيام ليعرض أمام هذا المجلس جواب الحكومة، يتلوه نقاش لا يعقبه تصويت.",
  "107": "السلطة القضائية مستقلة عن السلطة التشريعية وعن السلطة التنفيذية.\n\nالملك هو الضامن لاستقلال السلطة القضائية.",
  "108": "لا يعزل قضاة الأحكام ولا ينقلون إلا بمقتضى القانون.",
  "109": "يمنع كل تدخل في القضايا المعروضة على القضاء؛ ولا يتلقى القاضي بشأن مهمته القضائية أي أوامر أو تعليمات، ولا يخضع لأي ضغط.\n\nيجب على القاضي، كلما اعتبر أن استقلاله مهدد، أن يحيل الأمر إلى المجلس الأعلى للسلطة القضائية.\n\nيعد كل إخلال من القاضي بواجب الاستقلال والتجرد خطأ مهنيا جسيما، بصرف النظر عن المتابعات القضائية المحتملة.\n\nيعاقب القانون كل من حاول التأثير على القاضي بكيفية غير مشروعة.",
  "110": "لا يلزم قضاة الأحكام إلا بتطبيق القانون. ولا تصدر أحكام القضاء إلا على أساس التطبيق العادل للقانون.\n\nيجب على قضاة النيابة العامة تطبيق القانون. كما يتعين عليهم الالتزام بالتعليمات الكتابية القانونية الصادرة عن السلطة التي يتبعون لها.",
  "111": "للقضاة الحق في حرية التعبير، بما يتلاءم مع واجب التحفظ والأخلاقيات القضائية.\n\nيمكن للقضاة الانخراط في جمعيات، أو إنشاء جمعيات مهنية، مع احترام واجبات التجرد واستقلال القضاء، وطبقا للشروط المنصوص عليها في القانون.\n\nيُمنع على القضاة الانخراط في الأحزاب السياسية والمنظمات النقابية.",
  "112": "يُحدد النظام الأساسي للقضاة بقانون تنظيمي.",
  "113": "يسهرالمجلس الأعلى للسلطة القضائية على تطبيق الضمانات الممنوحة للقضاة، ولاسيما فيما يخص استقلالهم وتعيينهم وترقيتهم وتقاعدهم وتأديبهم.\n\nيضع المجلس الأعلى للسلطة القضائية، بمبادرة منه، تقارير حول وضعية القضاء ومنظومة العدالة، ويُصدر التوصيات الملائمة بشأنها.\n\nيُصدر المجلس الأعلى للسلطة القضائية، بطلب من الملك أو الحكومة أو البرلمان، آراء مفصلة حول كل مسألة تتعلق بالعدالة مع مراعاة مبدإ فصل السلط.",
  "114": "تكون المقررات المتعلقة بالوضعيات الفردية، الصادرة عن المجلس الأعلى للسلطة القضائية قابلة للطعن بسبب الشطط في استعمال السلطة، أمام أعلى هيئة قضائية إدارية بالمملكة.",
  "115": "يرأس الملك المجلس الأعلى للسلطة القضائية، ويتألف هذا المجلس من:\n\nالرئيس الأول لمحكمة النقض، رئيسا منتدبا؛\nالوكيل العام للملك لدى محكمة النقض؛\n\nرئيس الغرفة الأولى بمحكمة النقض؛\n\nأربعة ممثلين لقضاة محاكم الاستئناف، ينتخبهم هؤلاء القضاة من بينهم؛\n\nستة ممثلين لقضاة محاكم أول درجة، ينتخبهم هؤلاء القضاة من بينهم؛\n\nويجب ضمان تمثيلية النساء القاضيات من بين الأعضاء العشرة المنتخبين، بما يتناسب مع حضورهن داخل السلك القضائي؛\n\nالوسيط؛\n\nرئيس المجلس الوطني لحقوق الإنسان؛\n\nخمس شخصيات يعينها الملك، مشهود لها بالكفاءة والتجرد والنزاهة، والعطاء المتميز في سبيل استقلال القضاء وسيادة القانون؛ من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى.",
  "116": "يعقد المجلس الأعلى للسلطة القضائية دورتين في السنة على الأقل.\n\nيتوفر المجلس الأعلى للسلطة القضائية على الاستقلال الإداري والمالي.\n\nيساعد المجلس الأعلى للسلطة القضائية، في المادة التأديبية، قضاة مفتشون من ذوي الخبرة.\n\nيُحدد بقانون تنظيمي انتخاب وتنظيم وسير المجلس الأعلى للسلطة القضائية، والمعايير المتعلقة بتدبير الوضعية المهنية للقضاة، ومسطرة التأديب.\n\nيراعي المجلس الأعلى للسلطة القضائية، في القضايا التي تهم قضاة النيابة العامة، تقارير التقييم المقدمة من قبل السلطة التي يتبعون لها.",
  "117": "يتولى القاضي حماية حقوق الأشخاص والجماعات وحرياتهم وأمنهم القضائي، وتطبيق القانون.",
  "118": "حق التقاضي مضمون لكل شخص للدفاع عن حقوقه وعن مصالحه التي يحميها القانون.\n\nكل قرار اتخذ في المجال الإداري، سواء كان تنظيميا أو فرديا، يُمكن الطعن فيه أمام الهيئة القضائية الإدارية المختصة.",
  "119": "يعتبر كل مشتبه فيه أو متهم بارتكاب جريمة بريئا، إلى أن تثبت إدانته بمقرر قضائي مكتسب لقوة الشيء المقضي به.",
  "120": "لكل شخص الحق في محاكمة عادلة، وفي حكم يصدر داخل أجل معقول.\n\nحقوق الدفاع مضمونة أمام جميع المحاكم.",
  "121": "يكون التقاضي مجانيا في الحالات المنصوص عليها قانونا لمن لا يتوفر على موارد كافية للتقاضي.",
  "122": "يحق لكل من تضرر من خطإ قضائي الحصول على تعويض تتحمله الدولة.",
  "123": "تكون الجلسات علنية ماعدا في الحالات التي يقرر فيها القانون خلاف ذلك.",
  "124": "تصدر الأحكام وتنفذ باسم الملك وطبقا للقانون.",
  "125": "تكون الأحكام معللة وتصدر في جلسة علنية، وفق الشروط المنصوص عليها في القانون.",
  "126": "الأحكام النهائية الصادرة عن القضاء ملزمة للجميع.\n\nيجب على السلطات العمومية تقديم المساعدة اللازمة أثناء المحاكمة، إذا صدر الأمر إليها بذلك، ويجب عليها المساعدة على تنفيذ الأحكام.",
  "127": "تُحدث المحاكم العادية والمتخصصة بمقتضى القانون.\n\nلا يمكن إحداث محاكم استثنائية.",
  "128": "تعمل الشرطة القضائية تحت سلطة النيابة العامة وقضاة التحقيق، في كل ما يتعلق بالأبحاث والتحريات الضرورية في شأن الجرائم وضبط مرتكبيها ولإثبات الحقيقة.",
  "129": "تُحدث محكمة دستورية.",
  "130": "تتألف المحكمة الدستورية من اثني عشر عضوا، يعينون لمدة تسع سنوات غير قابلة للتجديد، ستة أعضاء يعينهم الملك، من بينهم عضو يقترحه الأمين العام للمجلس العلمي الأعلى، وستة أعضاء يُنتخب نصفهم من قبل مجلس النواب، وينتخب النصف الآخر من قبل مجلس المستشارين من بين المترشحين الذين يقدمهم مكتب كل مجلس، وذلك بعد التصويت بالاقتراع السري وبأغلبية ثلثي الأعضاء الذين يتألف منهم كل مجلس.\n\nإذا تعذر على المجلسين أو على أحدهما انتخاب هؤلاء الأعضاء، داخل الأجل القانوني للتجديد، تمارس المحكمة اختصاصاتها، وتصدر قراراتها، وفق نصاب لا يُحتسب فيه الأعضاء الذين لم يقع بعد انتخابهم.\n\nيتم كل ثلاث سنوات تجديد ثلث كل فئة من أعضاء المحكمة الدستورية.\n\nيعين الملك رئيس المحكمة الدستورية من بين الأعضاء الذين تتألف منهم.\n\nيختار أعضاء المحكمة الدستورية من بين الشخصيات المتوفرة على تكوين عال في مجال القانون، وعلى كفاءة قضائية أو فقهية أو إدارية، والذين مارسوا مهنتهم لمدة تفوق خمس عشرة سنة، والمشهود لهم بالتجرد والنزاهة.",
  "131": "يحدد قانون تنظيمي قواعد تنظيم المحكمة الدستورية وسيرها والإجراءات المتبعة أمامها، ووضعية أعضائها.\n\nيحدد القانون التنظيمي أيضا المهام التي لا يجوز الجمع بينها وبين عضوية المحكمة الدستورية، خاصة ما يتعلق منها بالمهن الحرة، وطريقة إجراء التجديدين الأولين لثلث أعضائها، وكيفيات تعيين من يحل محل أعضائها الذين استحال عليهم القيام بمهامهم، أو استقالوا أو توفوا أثناء مدة عضويتهم.",
  "132": "تمارس المحكمة الدستورية الاختصاصات المسندة إليها بفصول الدستور، وبأحكام القوانين التنظيمية، وتبت بالإضافة إلى ذلك في صحة انتخاب أعضاء البرلمان وعمليات الاستفتاء.\n\nتحال إلى المحكمة الدستورية القوانين التنظيمية قبل إصدار الأمر بتنفيذها، والأنظمة الداخلية لكل من مجلس النواب ومجلس المستشارين قبل الشروع في تطبيقها لتبت في مطابقتها للدستور.\n\nيمكن للملك، وكذا لكل من رئيس الحكومة، أو رئيس مجلس النواب، أو رئيس مجلس المستشارين، أو خُمس أعضاء مجلس النواب، أو أربعين عضوا من أعضاء مجلس المستشارين، أن يحيلوا القوانين، قبل إصدار الأمر بتنفيذها، إلى المحكمة الدستورية، لتبت في مطابقتها للدستور.\n\nتبت المحكمة الدستورية في الحالات المنصوص عليها في الفقرتين الثانية والثالثة من هذا الفصل، داخل أجل شهر من تاريخ الإحالة. غير أن هذا الأجل يُخفض في حالة الاستعجال إلى ثمانية أيام، بطلب من الحكومة.\n\nتؤدي الإحالة إلى المحكمة الدستورية في هذه الحالات، إلى وقف سريان أجل إصدار الأمر بالتنفيذ.\n\nتبت المحكمة الدستورية في الطعون المتعلقة بانتخاب أعضاء البرلمان، داخل أجل سنة، ابتداء من تاريخ انقضاء أجل تقديم الطعون إليها. غير أن للمحكمة تجاوز هذا الأجل بموجب قرار معلل، إذا استوجب ذلك عدد الطعون المرفوعة إليها، أو استلزم ذلك الطعن المقدم إليها.",
  "133": "تختص المحكمة الدستورية بالنظر في كل دفع متعلق بعدم دستورية قانون، أثير أثناء النظر في قضية، وذلك إذا دفع أحد الأطراف بأن القانون، الذي سيطبق في النزاع، يمس بالحقوق وبالحريات التي يضمنها الدستور.\n\nيحدد قانون تنظيمي شروط وإجراءات تطبيق هذا الفصل.",
  "134": "لا يمكن إصدار الأمر بتنفيذ مقتضى تم التصريح بعدم دستوريته على أساس الفصل 132 من هذا الدستور، ولا تطبيقه، وينسخ كل مقتضى تم التصريح بعدم دستوريته على أساس الفصل 133 من الدستور، ابتداء من التاريخ الذي حددته المحكمة الدستورية في قرارها.\n\nلا تقبل قرارات المحكمة الدستورية أي طريق من طرق الطعن، وتلزم كل السلطات العامة وجميع الجهات الإدارية والقضائية.",
  "135": "الجماعات الترابية للمملكة هي الجهات، والعمالات والأقاليم، والجماعات.\n\nالجماعات الترابية أشخاص معنوية، خاضعة للقانون العام، تسير شؤونها بكيفية ديمقراطية.\n\nتنتخب مجالس الجهات والجماعات بالاقتراع العام المباشر.\n\nتحدث كل جماعة ترابية أخرى بمقتضى القانون، ويمكن أن تحل محل جماعة أو أكثر من الجماعات الترابية المنصوص عليها في الفقرة الأولى من هذا الفصل.",
  "136": "يقوم التنظيم الجهوي والترابي على مبادئ التدبير الحر، وعلى التعاون والتضامن؛ ويضمن مشاركة السكان المعنيين في تدبير شؤونهم، والرفع من مساهمتهم في التنمية البشرية المندمجة والمستدامة.",
  "137": "تساهم الجهات والجماعات الترابية الأخرى في تنفيذ السياسة العامة للدولة، وفي إعداد السياسات الترابية، من خلال ممثليها في مجلس المستشارين.",
  "138": "يقوم رؤساء مجالس الجهات، ورؤساء مجالس الجماعات الترابية الأخرى، بتنفيذ مداولات هذه المجالس ومقرراتها.",
  "139": "تضع مجالس الجهات، والجماعات الترابية الأخرى، آليات تشاركية للحوار والتشاور، لتيسير مساهمة المواطنات والمواطنين والجمعيات في إعداد برامج التنمية وتتبعها.\n\nيمكن للمواطنات والمواطنين والجمعيات تقديم عرائض، الهدف منها مطالبة المجلس بإدراج نقطة تدخل في اختصاصه ضمن جدول أعماله.",
  "140": "للجهات والجماعات الترابية الأخرى، بناء على مبدأ التفريع، اختصاصات ذاتية واختصاصات مشتركة مع الدولة واختصاصات منقولة إليها من هذه الأخيرة.\n\nتتوفر الجهات والجماعات الترابية الأخرى، في مجالات اختصاصاتها، وبداخل دائرتها الترابية، على سلطة تنظيمية لممارسة صلاحياتها.",
  "141": "تتوفر الجهات والجماعات الترابية الأخرى على موارد مالية ذاتية، وموارد مالية مرصودة من قبل الدولة.\n\nكل اختصاص تنقله الدولة إلى الجهات والجماعات الترابية الأخرى يكون مصحوبا بتحويل الموارد المطابقة له.",
  "142": "يُحدث لفائدة الجهات صندوق للتأهيل الاجتماعي، يهدف إلى سد العجز في مجالات التنمية البشرية، والبنيات التحتية الأساسية والتجهيزات.\n\nيُحدث أيضا صندوق للتضامن بين الجهات، بهدف التوزيع المتكافئ للموارد، قصد التقليص من التفاوتات بينها.",
  "143": "لا يجوز لأي جماعة ترابية أن تمارس وصاية على جماعة أخرى.\n\nتبوأ الجهة، تحت إشراف رئيس مجلسها، مكانة الصدارة بالنسبة للجماعات الترابية الأخرى، في عمليات إعداد وتتبع برامج التنمية الجهوية، والتصاميم الجهوية لإعداد التراب، وذلك في إطار احترام الاختصاصات الذاتية لكل جماعة ترابية.\n\nكلما استوجب إنجاز مشروع يتطلب مساهمة عدة جماعات ترابية، اتفقت الجماعات المعنية على كيفيات تعاونها.",
  "144": "يمكن للجهات والجماعات الترابية الأخرى تأسيس مجموعات فيما بينها، قصد إنجاز مشاريع مشتركة، وفق القواعد المنصوص عليها في القانون.",
  "145": "يمثل ولاة الجهات وعمال العمالات والأقاليم، السلطة المركزية في الجماعات الترابية.\n\nيعمل الولاة والعمال، باسم الحكومة، على تأمين تطبيق القانون، وتنفيذ النصوص التنظيمية للحكومة ومقرراتها، كما يمارسون المراقبة الإدارية.\n\nيساعد الولاة والعمال رؤساء الجماعات الترابية، وخاصة رؤساء مجالس الجهات، على تنفيذ المخططات والبرامج التنموية.\n\nيقوم الولاة والعمال، تحت سلطة الوزراء المعنيين، بتنسيق أنشطة المصالح اللاممركزة للإدارة المركزية، والسهر على حسن سيرها.",
  "146": "يحدد قانون تنظيمي بصفة خاصة:\n\nشروط تدبير الجهات والجماعات الترابية الأخرى لشؤونها بكيفية ديمقراطية، وعدد أعضاء مجالسها، والقواعد المتعلقة بأهلية الترشيح، وحالات التنافي، وحالات منع الجمع بين الانتدابات، وكذا النظام الانتخابي، وأحكام تحسين تمثيلية النساء داخل المجالس المذكورة؛\nشروط تنفيذ رؤساء مجالس الجهات ورؤساء مجالس الجماعات الترابية الأخرى لمداولات هذه المجالس ومقرراتها، طبقا للفصل 138؛\n\nشروط تقديم العرائض المنصوص عليها في الفصل 139 من قبل المواطنات والمواطنين والجمعيات؛\n\nالاختصاصات الذاتية لفائدة الجهات والجماعات الترابية الأخرى، والاختصاصات المشتركة بينها وبين الدولة والاختصاصات المنقولة إليها طبقا للفصل 140؛\n\nالنظام المالي للجهات والجماعات الترابية الأخرى، ومصدر مواردها المالية المنصوص عليها في الفصل 141؛\n\nمساطر وكيفيات تحويل الموارد المطابقة لنقل الاختصاصات من الدولة إلى الجهات والجماعات الترابية الأخرى؛\n\nشروط وكيفيات تأسيس المجموعات المشار إليها في الفصل 144؛\n\nالمقتضيات الميسرة للتعاون بين الجماعات، وكذا الآليات الرامية إلى ضمان تطور التنظيم الترابي في اتجاه التضامن؛\n\nقواعد الحكامة المتعلقة بحسن تطبيق مبدأ التدبير الحر، وكذا مراقبة تدبير الصناديق والبرامج وتقييم الأعمال وإجراءات المحاسبة.",
  "147": "المجلس الأعلى للحسابات هو الهيئة العليا لمراقبة المالية العمومية بالمملكة، ويضمن الدستور استقلاله.\n\nيتولى المجلس الأعلى للحسابات تدعيم وحماية مبادئ وقيم الحكامة الجيدة والشفافية والمحاسبة، بالنسبة للدولة والأجهزة العمومية.\n\nيتولى المجلس الأعلى للحسابات مراقبة تنفيذ القوانين المالية، ويتحقق من سلامة العمليات المتعلقة بمداخيل ومصاريف الأجهزة الخاضعة لمراقبته بمقتضى القانون، ويقيم كيفية تدبيرها لشؤونها، ويعاقب عند الاقتضاء على الأخطاء المتعلقة بالتدبير المعروضة عليه.\n\nيبت المجلس الأعلى للحسابات في الحسابات التي تقدمها الهيئات والمؤسسات الخاضعة لمراقبته.\n\nيتولى المجلس الأعلى للحسابات مراقبة وتتبع التصريح بالممتلكات، وتدقيق حسابات الأحزاب السياسية، وفحص نفقاتها المتعلقة بالعمليات الانتخابية.",
  "148": "يعاون المجلس الأعلى للحسابات البرلمان في المجالات المتعلقة بمراقبة المالية العمومية. ويجيب عن الأسئلة والاستشارات المرتبطة بوظائف البرلمان في التشريع والمراقبة والتقييم، المتعلقة بالمالية العمومية.\n\nيعاون المجلس الأعلى للحسابات الحكومة، في المجالات التي تدخل في نطاق اختصاصاته بمقتضى القانون.\n\nينشر المجلس الأعلى للحسابات جميع أعماله، بما فيها التقارير الخاصة والمقررات القضائية.\n\nيرفع المجلس الأعلى للحسابات للملك تقريرا سنويا، يتضمن بيان جميع أعماله، ويوجهه أيضا إلى رئيس الحكومة، وإلى رئيسي مجلسي البرلمان، ويُنشر في الجريدة الرسمية للمملكة.\n\nيُقدم رئيس المجلس الأعلى للحسابات عرضا عن أعمال المجلس أمام البرلمان، ويتلو ذلك مناقشة.",
  "149": "تتولى المجالس الجهوية للحسابات مراقبة حسابات الجهات والجماعات الترابية الأخرى وهيئاتها، وكيفية تدبير شؤونها.\n\nويعاقب عند الاقتضاء على الأخطاء المتعلقة بالتدبير المعروضة عليه.",
  "150": "يحدد القانون اختصاصات المجلس الأعلى للحسابات والمجالس الجهوية للحسابات، وقواعد تنظيمها، وكيفية سيرها.",
  "151": "يحدث مجلس اقتصادي واجتماعي وبيئي.",
  "152": "للحكومة ولمجلس النواب ولمجلس المستشارين أن يستشيروا المجلس الاقتصادي والاجتماعي والبيئي في جميع القضايا، التي لها طابع اقتصادي واجتماعي وبيئي.\n\nيدلي المجلس برأيه في التوجهات العامة للاقتصاد الوطني والتنمية المستدامة.",
  "153": "يحدد قانون تنظيمي تأليف المجلس الاقتصادي والاجتماعي والبيئي، وتنظيمه، وصلاحياته، وكيفيات تسييره.",
  "154": "يتم تنظيم المرافق العمومية على أساس المساواة بين المواطنات والمواطنين في الولوج إليها، والإنصاف في تغطية التراب الوطني، والاستمرارية في أداء الخدمات.\n\nتخضع المرافق العمومية لمعايير الجودة والشفافية والمحاسبة والمسؤولية، وتخضع في تسييرها للمبادئ والقيم الديمقراطية التي أقرها الدستور.",
  "155": "يمارس أعوان المرافق العمومية وظائفهم، وفقا لمبادئ احترام القانون والحياد والشفافية والنزاهة والمصلحة العامة.",
  "156": "تتلقى المرافق العمومية ملاحظات مرتفقيها، واقتراحاتهم وتظلماتهم، وتؤمن تتبعها.\n\nتقدم المرافق العمومية الحساب عن تدبيرها للأموال العمومية، طبقا للقوانين الجاري بها العمل، وتخضع في هذا الشأن للمراقبة والتقييم.",
  "157": "يحدد ميثاق للمرافق العمومية قواعد الحكامة الجيدة المتعلقة بتسيير الإدارات العمومية والجهات والجماعات الترابية الأخرى والأجهزة العمومية.",
  "158": "يجب على كل شخص، منتخبا كان أو معينا، يمارس مسؤولية عمومية، أن يقدم، طبقا للكيفيات المحددة في القانون، تصريحا كتابيا بالممتلكات والأصول التي في حيازته، بصفة مباشرة أو غير مباشرة، بمجرد تسلمه لمهامه، وخلال ممارستها وعند انتهائها.",
  "159": "تكون الهيئات المكلفة بالحكامة الجيدة مستقلة؛ وتستفيد من دعم أجهزة الدولة؛ ويمكن للقانون أن يُحدث عند الضرورة، علاوة على المؤسسات والهيئات المذكورة بعده، هيئات أخرى للضبط والحكامة الجيدة.",
  "160": "على المؤسسات والهيئات المشار إليها في الفصول 161 إلى 170 من هذا الدستور تقديم تقرير عن أعمالها، مرة واحدة في السنة على الأقل، الذي يكون موضوع مناقشة من قبل البرلمان.",
  "161": "المجلس الوطني لحقوق الإنسان مؤسسة وطنية تعددية ومستقلة، تتولى النظر في جميع القضايا المتعلقة بالدفاع عن حقوق الإنسان والحريات وحمايتها، وبضمان ممارستها الكاملة، والنهوض بها وبصيانة كرامة وحقوق وحريات المواطنات والمواطنين، أفرادا وجماعات، وذلك في نطاق الحرص التام على احترام المرجعيات الوطنية والكونية في هذا المجال.",
  "162": "الوسيط مؤسسة وطنية مستقلة ومتخصصة، مهمتها الدفاع عن الحقوق في نطاق العلاقات بين الإدارة والمرتفقين، والإسهام في ترسيخ سيادة القانون، وإشاعة مبادئ العدل والإنصاف، وقيم التخليق والشفافية في تدبير الإدارات والمؤسسات العمومية والجماعات الترابية والهيئات التي تمارس صلاحيات السلطة العمومية.",
  "163": "يتولى مجلس الجالية المغربية بالخارج، على الخصوص، إبداء آرائه حول توجهات السياسات العمومية التي تمكن المغاربة المقيمين بالخارج من تأمين الحفاظ على علاقات متينة مع هويتهم المغربية، وضمان حقوقهم وصيانة مصالحهم، وكذا المساهمة في التنمية البشرية والمستدامة في وطنهم المغرب وتقدمه.",
  "164": "تسهر الهيأة المكلفة بالمناصفة ومحاربة جميع أشكال التمييز، المحدثة بموجب الفصل 19 من هذا الدستور، بصفة خاصة، على احترام الحقوق والحريات المنصوص عليها في الفصل المذكور، مع مراعاة الاختصاصات المسندة للمجلس الوطني لحقوق الإنسان.",
  "165": "تتولى الهيئة العليا للاتصال السمعي البصري السهر على احترام التعبير التعددي لتيارات الرأي والفكر، والحق في المعلومة في الميدان السمعي البصري، وذلك في إطار احترام القيم الحضارية الأساسية وقوانين المملكة.",
  "166": "مجلس المنافسة هيئة مستقلة، مكلفة في إطار تنظيم منافسة حرة ومشروعة بضمان الشفافية والإنصاف في العلاقات الاقتصادية، خاصة من خلال تحليل وضبط وضعية المنافسة في الأسواق، ومراقبة الممارسات المنافية لها والممارسات التجارية غير المشروعة وعمليات التركيز الاقتصادي والاحتكار.",
  "167": "تتولى الهيئة الوطنية للنزاهة والوقاية من الرشوة ومحاربتها، المحدثة بموجب الفصل 36، على الخصوص، مهام المبادرة والتنسيق والإشراف وضمان تتبع تنفيذ سياسات محاربة الفساد، وتلقي ونشر المعلومات في هذا المجال، والمساهمة في تخليق الحياة العامة، وترسيخ مبادئ الحكامة الجيدة، وثقافة المرفق العام، وقيم المواطنة المسؤولة.",
  "168": "يحدث مجلس أعلى للتربية والتكوين والبحث العلمي.\n\nالمجلس هيئة استشارية، مهمتها إبداء الآراء حول كل السياسات العمومية، والقضايا الوطنية التي تهم التربية والتكوين والبحث العلمي، وكذا حول أهداف المرافق العمومية المكلفة بهذه الميادين وسيرها. كما يساهم في تقييم السياسات والبرامج العمومية في هذا المجال.",
  "169": "يتولى المجلس الاستشاري للأسرة والطفولة، المحدث بموجب الفصل 32 من هذا الدستور، مهمة تأمين تتبع وضعية الأسرة والطفولة، وإبداء آراء حول المخططات الوطنية المتعلقة بهذه الميادين، وتنشيط النقاش العمومي حول السياسة العمومية في مجال الأسرة، وضمان تتبع وإنجاز البرامج الوطنية، المقدمة من قبل مختلف القطاعات، والهياكل والهيئات المختصة.",
  "170": "يعتبر المجلس الاستشاري للشباب والعمل الجمعوي، المحدث بموجب الفصل 33 من هذا الدستور، هيئة استشارية في ميادين حماية الشباب والنهوض بتطوير الحياة الجمعوية. وهو مكلف بدراسة وتتبع المسائل التي تهم هذه الميادين، وتقديم اقتراحات حول كل موضوع اقتصادي واجتماعي وثقافي، يهم مباشرة النهوض بأوضاع الشباب والعمل الجمعوي، وتنمية طاقاتهم الإبداعية، وتحفيزهم على الانخراط في الحياة الوطنية، بروح المواطنة المسؤولة.",
  "171": "يحدد بقوانين تأليف وصلاحيات وتنظيم وقواعد تسيير المؤسسات والهيئات المنصوص عليها في الفصول 161 إلى 170 من هذا الدستور، وكذا حالات التنافي عند الاقتضاء.",
  "172": "للملك ولرئيس الحكومة ولمجلس النواب ولمجلس المستشارين، حق اتخاذ المبادرة قصد مراجعة الدستور.\n\nللملك أن يعرض مباشرة على الاستفتاء، المشروع الذي اتخذ المبادرة بشأنه.",
  "173": "لا تصح الموافقة على مقترح مراجعة الدستور الذي يتقدم به عضو أو أكثر من أعضاء أحد مجلسي البرلمان، إلا بتصويت أغلبية ثلثي الأعضاء الذين يتألف منهم المجلس.\n\nيُحال المقترح إلى المجلس الآخر، الذي يوافق عليه بنفس أغلبية ثلثي الأعضاء الذين يتألف منهم.\n\nيُعرض المقترح الذي يتقدم به رئيس الحكومة على المجلس الوزاري، بعد التداول بشأنه في مجلس الحكومة.",
  "174": "تُعرض مشاريع ومقترحات مراجعة الدستور، بمقتضى ظهير، على الشعب قصد الاستفتاء.\n\nتكون المراجعة نهائية بعد إقرارها بالاستفتاء.\n\nللملك، بعد استشارة رئيس المحكمة الدستورية، أن يعرض بظهير، على البرلمان، مشروع مراجعة بعض مقتضيات الدستور.\n\nويصادق البرلمان، المنعقد، بدعوة من الملك، في اجتماع مشترك لمجلسيه، على مشروع هذه المراجعة، بأغلبية ثلثي الأعضاء الذين يتألف منهم.\n\nيحدد النظام الداخلي لمجلس النواب كيفيات تطبيق هذا المقتضى.\n\nتراقب المحكمة الدستورية صحة إجراءات هذه المراجعة، وتعلن نتيجتها.",
  "175": "لا يمكن أن تتناول المراجعة الأحكام المتعلقة بالدين الإسلامي، وبالنظام الملكي للدولة، وبالاختيار الديمقراطي للأمة، وبالمكتسبات في مجال الحريات والحقوق الأساسية المنصوص عليها في هذا الدستور.",
  "176": "إلى حين انتخاب مجلسي البرلمان، المنصوص عليهما في هذا الدستور، يستمر المجلسان القائمان حاليا في ممارسة صلاحياتهما، ليقوما على وجه الخصوص، بإقرار القوانين اللازمة لتنصيب مجلسي البرلمان الجديدين، وذلك دون إخلال بالأحكام المنصوص عليها في الفصل 51 من هذا الدستور.",
  "177": "يستمر المجلس الدستوري القائم حاليا في ممارسة صلاحياته، إلى أن يتم تنصيب المحكمة الدستورية، المنصوص عليها في هذا الدستور.",
  "178": "يستمر المجلس الأعلى للقضاء في ممارسة صلاحياته، إلى أن يتم تنصيب المجلس الأعلى للسلطة القضائية، المنصوص عليه في هذا الدستور.",
  "179": "تظل النصوص المتعلقة بالمؤسسات والهيئات المذكورة في الباب الثاني عشر من هذا الدستور، وكذا تلك المتعلقة بالمجلس الاقتصادي والاجتماعي وبالمجلس الأعلى للتعليم، سارية المفعول، إلى حين تعويضها، طبقا لمقتضيات هذا الدستور.",
  "180": "مع مراعاة المقتضيات الانتقالية الواردة في هذا الباب، يُنسخ نص الدستور المراجع الصادر بتنفيذه الظهير الشريف رقم 1.96.157، المؤرخ في 23 من جمادى الأولى 1417 (07 أكتوبر 1996).",
};
